package com.smartgrading.backend.controller;
import com.smartgrading.backend.dto.EvaluationResponse; import com.smartgrading.backend.service.EvaluationService; import java.util.List; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1") public class EvaluationController { private final EvaluationService service; public EvaluationController(EvaluationService s){service=s;} @PostMapping("/submissions/{submissionId}/evaluate") public List<EvaluationResponse> evaluate(@PathVariable Integer submissionId){return service.evaluateSubmission(submissionId);} @GetMapping("/answers/{answerId}/evaluation") public List<EvaluationResponse> byAnswer(@PathVariable Integer answerId){return service.byAnswer(answerId).stream().map(EvaluationResponse::from).toList();} }
